mapper.select:
select u.id, u.username, u.nickname, u.avatar, u.status
from conversation_members cm
join users u on u.id = cm.user_id
where cm.conversation_id = #{conversationId}
order by cm.id
limit #{size} offset #{offset}

mapper.update:
update conversation_members
set last_read_msg_id = #{lastReadMsgId}
where conversation_id = #{conversationId} and user_id = #{userId}

mapper.select:
select m.conversation_id, count(*) as `count`
from chat_messages m
join conversation_members me
     on me.conversation_id = m.conversation_id and me.user_id = #{userId}
where me.last_read_msg_id < m.id and m.sender_id <> #{userId}
group by m.conversation_id

mapper.update:
update conversations
name=#{name}, avatar=#{avatar}, notice=#{notice}, update_time=now()
where id=#{conversationId}
